def _new_game_with_two_players():
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    return game, p1, p2


def _create_in_hand(game, player, name):
    """Create the card in the player's HAND without firing interceptor setup."""
    cdef = WILDS_OF_ELDRAINE_CARDS[name]
    obj = game.create_object(
        name=name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=cdef.characteristics,
        card_def=None,  # delay setup until ZONE_CHANGE -> battlefield
    )
    obj.card_def = cdef
    return obj


def _move_to_battlefield(game, obj, player):
    """Move from HAND to BATTLEFIELD via ZONE_CHANGE so interceptors set up + ETB fires."""
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{player.id}',
            'to_zone': 'battlefield',
            'to_zone_type': ZoneType.BATTLEFIELD,
        }
    ))


