def test_harried_spearguard():
    """<name>: death trigger emits one of ['OBJECT_CREATED']."""
    game, p1, p2 = _new_game_with_two_players()
    _seed_board(game, p1, p2)
    card = _create_in_hand(game, p1,'Harried Spearguard')
    _move_to_battlefield(game, card, p1)
    before = _event_log_len(game)
    # Send the creature to the graveyard
    gy_zone = f"graveyard_{p1.id}"
    if gy_zone not in game.state.zones:
        from src.engine import Zone
        game.state.zones[gy_zone] = Zone(id=gy_zone, zone_type=ZoneType.GRAVEYARD)
    game.emit(Event(
        type=EventType.OBJECT_DESTROYED,
        payload={'object_id': card.id, 'reason': 'lethal damage'},
    ))
    # If still on battlefield, emit ZONE_CHANGE BF->GY
    obj = game.state.objects.get(card.id)
    if obj and obj.zone == ZoneType.BATTLEFIELD:
        game.emit(Event(
            type=EventType.ZONE_CHANGE,
            payload={
                'object_id': card.id,
                'from_zone': 'battlefield',
                'to_zone': gy_zone,
                'from_zone_type': ZoneType.BATTLEFIELD,
                'to_zone_type': ZoneType.GRAVEYARD,
            }
        ))
    _assert_expected_event_emitted(game, before, {EventType.OBJECT_CREATED}, 'Harried Spearguard', "death")
